"""Self-check for check_gradle_verification_metadata.py.

The CI run only sees the metadata of the pull request at hand; these cases pin the branches that
must reject (a changed checksum, an <also-trust> slipped into an existing entry) and the ones that
must pass (new versions, dropped versions, warning mode without --enforce).
"""

import subprocess
import sys
from pathlib import Path

SCRIPT = Path(__file__).resolve().parent / "check_gradle_verification_metadata.py"

A = "a" * 64
B = "b" * 64
C = "c" * 64


def metadata(*components: str) -> str:
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<verification-metadata xmlns="https://schema.gradle.org/dependency-verification">\n'
        "   <components>\n" + "".join(components) + "   </components>\n</verification-metadata>\n"
    )


def component(version: str, sha: str, also: str | None = None) -> str:
    inner = (
        f'<sha256 value="{sha}" origin="Generated by Gradle"/>'
        if also is None
        else f'<sha256 value="{sha}" origin="Generated by Gradle">\n'
        f'<also-trust value="{also}"/>\n</sha256>'
    )
    return (
        f'<component group="org.example" name="lib" version="{version}">\n'
        f'<artifact name="lib-{version}.jar">\n{inner}\n</artifact>\n</component>\n'
    )


def run(tmp_path: Path, base: str, head: str, *flags: str) -> subprocess.CompletedProcess:
    (tmp_path / "base.xml").write_text(base, encoding="utf-8")
    (tmp_path / "head.xml").write_text(head, encoding="utf-8")
    return subprocess.run(
        [sys.executable, str(SCRIPT), str(tmp_path / "base.xml"), str(tmp_path / "head.xml"), *flags],
        capture_output=True,
        text=True,
    )


def test_new_and_dropped_versions_pass(tmp_path):
    result = run(
        tmp_path,
        metadata(component("1.0", A), component("1.1", B)),
        metadata(component("1.1", B), component("1.2", C)),
        "--enforce",
    )
    assert result.returncode == 0, result.stdout
    assert "1 artifact file(s) added, 1 removed, 0 with changed checksums" in result.stdout


def test_changed_checksum_fails_when_enforced(tmp_path):
    result = run(tmp_path, metadata(component("1.0", A)), metadata(component("1.0", B)), "--enforce")
    assert result.returncode == 1
    assert "::error::org.example:lib:1.0 lib-1.0.jar" in result.stdout


def test_also_trust_added_to_existing_entry_fails_when_enforced(tmp_path):
    result = run(
        tmp_path, metadata(component("1.0", A)), metadata(component("1.0", A, also=B)), "--enforce"
    )
    assert result.returncode == 1
    assert "::error::" in result.stdout


def test_changed_checksum_only_warns_without_enforce(tmp_path):
    result = run(tmp_path, metadata(component("1.0", A)), metadata(component("1.0", B)))
    assert result.returncode == 0
    assert "::warning::org.example:lib:1.0 lib-1.0.jar" in result.stdout


def test_repository_metadata_parses(tmp_path):
    repo_file = SCRIPT.parents[2] / "backend" / "gradle" / "verification-metadata.xml"
    text = repo_file.read_text(encoding="utf-8")
    result = run(tmp_path, metadata(), text, "--enforce")
    assert result.returncode == 0, result.stdout
    assert int(result.stdout.split()[0]) > 1000, result.stdout
